let pendingMessageEdit=null;
function messageActions(m,i,c){return `<div class="message-actions" aria-label="消息操作">${m.text?`<button data-action="message-copy:${c.id}:${i}" title="复制消息">${svg('copy')}<span>复制</span></button>`:''}${m.role==='user'?`<button data-action="message-edit:${c.id}:${i}" ${stream?'disabled title="请先停止或等待当前生成完成"':'title="编辑后在当前会话重发送"'}>${svg('edit')}<span>编辑重发</span></button>${stream?'<span class="action-note">生成中，暂不可编辑</span>':''}`:''}${m.error?`<button data-action="message-retry:${c.id}:${i}" ${stream?'disabled':''}>${svg('retry')}<span>重试</span></button>`:''}</div>`}
async function copyMessage(cid,index){const m=conversations.find(c=>c.id===cid)?.messages[index];if(!m)return;try{if(!navigator.clipboard?.writeText)throw new Error('unavailable');await navigator.clipboard.writeText(m.text);toast('已复制消息')}catch(e){if(dialog.open)closeDialog();openDialog('手动复制消息',`<p class="dialog-note">浏览器未允许自动复制。请选中文字后使用系统复制。</p><textarea id="manual-message-copy" aria-label="待复制消息" readonly>${esc(m.text)}</textarea><div class="dialog-actions"><button class="primary" data-action="close">完成</button></div>`);dialog.querySelector('textarea').select()}}
function editMessage(cid,index){if(stream){toast('请先停止或等待当前生成完成');return}const c=conversations.find(c=>c.id===cid),m=c?.messages[index];if(m?.role!=='user')return;pendingMessageEdit={cid,index,original:m.text,snapshot:JSON.parse(JSON.stringify({experts:m.sendContext?.experts||c.experts,model:c.model||defaultModel,reasoningEffort:c.desktopEffort||c.reasoningEffort||'自动',permissionMode:c.permissionMode||'谨慎'})),submitted:false};openDialog('编辑并重发送',`<p class="dialog-note">保存后原地替换这条消息并静默移除其后的轮次，在当前会话重新生成。编辑点之前的历史与输入框草稿保持不变。此处仅演示交互。</p><label for="resend-text">消息内容</label><textarea id="resend-text" rows="5">${esc(m.text)}</textarea><p class="dialog-note">当前会话配置：Nola${pendingMessageEdit.snapshot.experts.length?'（协作专家：'+esc(pendingMessageEdit.snapshot.experts.join('、'))+'）':''} · ${esc(pendingMessageEdit.snapshot.model)}</p><p id="resend-error" role="status" class="dialog-note"></p><div class="dialog-actions"><button class="text-action" data-action="message-edit-cancel">取消</button><button class="primary" data-action="message-edit-submit">保存并重发送</button></div>`);const t=dialog.querySelector('#resend-text'),b=dialog.querySelector('[data-action="message-edit-submit"]');t.oninput=()=>b.disabled=!t.value.trim();t.focus()}
function submitMessageEdit(){const e=pendingMessageEdit,t=dialog.querySelector('#resend-text')?.value.trim();if(!e||e.submitted)return;if(!t){dialog.querySelector('#resend-error').textContent='消息不能为空';return}if(stream){dialog.querySelector('#resend-error').textContent='请先停止或等待当前生成完成';return}const original=conversations.find(c=>c.id===e.cid);if(!original||original.messages[e.index]?.text!==e.original){dialog.querySelector('#resend-error').textContent='原消息已变化，请重新打开编辑';return}e.submitted=true;dialog.querySelector('[data-action="message-edit-submit"]').disabled=true;const snap=e.snapshot;original.messages.splice(e.index,original.messages.length-e.index,{role:'user',text:t,sendContext:JSON.parse(JSON.stringify(snap))},{role:'Nola',text:`已按修改后的消息重新整理：\n\n${t}\n\n这是当前会话的本地演示回复。编辑点之前的内容保留，后续轮次已原地替换。`,...(snap.experts.length?{expertTasks:snap.experts.map(name=>({name,status:'已完成',summary:'已按更新后的消息完成子任务核对并交回 Nola。'}))}:{})});original.preview=t;original.time='刚刚';pendingMessageEdit=null;closeDialog();navigate('chat',original.id);toast('已在当前会话重发送')}
